"""STRIDE threats generated by the threat-modeling engine."""
from sqlalchemy import Index

from app.extensions import db
from app.utils import utcnow

STRIDE_CATEGORIES = {
    "S": "Spoofing",
    "T": "Tampering",
    "R": "Repudiation",
    "I": "Information Disclosure",
    "D": "Denial of Service",
    "E": "Elevation of Privilege",
}
THREAT_STATUSES = ("potential", "observed", "confirmed", "needs_review", "mitigated")
CONFIDENCE_LEVELS = ("low", "medium", "high")


class STRIDEThreat(db.Model):
    __tablename__ = "stride_threats"
    id = db.Column(db.Integer, primary_key=True)
    organization_id = db.Column(db.Integer, db.ForeignKey("organizations.id", ondelete="CASCADE"),
                                nullable=False, index=True)
    asset_id = db.Column(db.Integer, db.ForeignKey("assets.id", ondelete="CASCADE"),
                         nullable=False, index=True)
    category_code = db.Column(db.String(1), nullable=False)  # S T R I D E
    title = db.Column(db.String(255), nullable=False)
    description = db.Column(db.Text, default="")
    # List of {"source": "...", "detail": "..."} evidence items.
    evidence = db.Column(db.JSON, default=list)
    severity = db.Column(db.String(10), default="medium", index=True)
    confidence = db.Column(db.String(10), default="medium", index=True)
    status = db.Column(db.String(20), default="potential", nullable=False, index=True)
    mitigation = db.Column(db.Text, default="")
    # Which engine rule / user produced it; manual threats keep threat_key NULL.
    threat_key = db.Column(db.String(120), index=True)
    # Fingerprint so engine re-runs update existing threats instead of duplicating.
    fingerprint = db.Column(db.String(64), index=True)
    created_at = db.Column(db.DateTime, default=utcnow, nullable=False)
    updated_at = db.Column(db.DateTime, default=utcnow, onupdate=utcnow, nullable=False)

    asset = db.relationship("Asset", backref=db.backref("threats", lazy="select",
                                                        cascade="all, delete-orphan"))

    __table_args__ = (
        Index("ix_threat_org_cat", "organization_id", "category_code"),
    )

    @property
    def category_name(self) -> str:
        return STRIDE_CATEGORIES.get(self.category_code, self.category_code)
